-- SQL : relation stricte entre tables
SELECT commandes.id, users.pseudo
FROM commandes
JOIN users ON commandes.user_id = users.id;

// NoSQL (document, ex: MongoDB) : données imbriquées
{ _id: 1, pseudo: 'aissatou', commandes: [{ id: 1, total: 4500 }] }

-- Un index accélère les lectures par email, au prix d'un coût à chaque écriture
CREATE INDEX idx_users_email ON users(email);

// NoSQL : la donnée peut être dupliquée volontairement (dénormalisation) pour éviter les jointures,
// au prix d'un risque d'incohérence si elle change ailleurs sans être resynchronisée

// Monolithe : tout dans une seule app
app.use('/users', usersRouter);
app.use('/orders', ordersRouter);
app.use('/payments', paymentsRouter);

// Microservices : chaque domaine est un service séparé
// users-service:3001, orders-service:3002, payments-service:3003

// Monolithe modulaire : un compromis, modules séparés mais un seul déploiement
app.use('/users', usersModule.router); // frontière claire, mais toujours un seul process

// Un API Gateway route les requêtes clients vers le bon microservice, en cachant la complexité interne

// Exemple simple de cache avec Redis (pseudo-code)
const cached = await redis.get(`user:${id}`);
if (cached) return JSON.parse(cached);

const user = await db.user.findUnique({ where: { id } });
await redis.set(`user:${id}`, JSON.stringify(user), 'EX', 60); // expire après 60s
return user;

// Variante : invalider explicitement le cache dès qu'on modifie la donnée en base
await db.user.update({ where: { id }, data: changes });
await redis.del(`user:${id}`); // évite de servir une version périmée jusqu'à expiration du TTL
